CREATE FUNCTION [dbo].[LIST_SALARY_END](@Forms___F_MENU_BIM___MMO [int], @Forms___Baseknow___HOLA [int], @Forms___Baseknow___HSAY [int], @Forms___Baseknow___HJAZ [int], @Forms___Baseknow___HNAH [int], @Forms___Baseknow___HCON [int], @Forms___Baseknow___HKHA [int], @HOKMDATE [bigint], @Forms___Baseknow___HSANP [int], @Forms___Baseknow___HSHI [int], @Forms___Baseknow___YEA [smallint], @Forms___Baseknow___HEZA [int], @Forms___Baseknow___HBON [int], @Forms___Baseknow___HTAHOL [INT]) RETURNS TABLE AS RETURN (SELECT dbo.PERSONEL.CODE, dbo.PERSONEL.PNAME, dbo.PERSONEL.PFAMILY, dbo.PERSONEL.PNAME + ' ' + dbo.PERSONEL.PFAMILY AS PNPF, dbo.PERSONEL.KHNOWNUM, dbo.PERSONEL.FATHER, dbo.PERSONEL.BIMEH_NUM, dbo.PERSONEL.JOB, dbo.PERSONEL.SEX, dbo.UIIF(dbo.Uyear(dbo.PERSONEL.WSDATE) * 100 + dbo.Umonth(dbo.PERSONEL.WSDATE), N'>=', @Forms___Baseknow___YEA * 100 + @Forms___F_MENU_BIM___MMO, dbo.PERSONEL.WSDATE, NULL) AS WSDAT, dbo.PERSONEL.WEDATE, dbo.WORKING.WDATE, dbo.WORKING.DAYS, dbo.WORKING.EZAFAH, dbo.WORKING.PADASH, dbo.WORKING.KASR_VAM, dbo.Umonth(dbo.WORKING.WDATE) AS MM, dbo.PERSONEL.DSW_IDPLC, dbo.PERSONEL.DSW_NAT, dbo.PERSONEL.DSW_BDATE, dbo.PHOKM.HONUM, dbo.PHOKM.HDATE AS MaxOfHDATE, dbo.PHOKM.SALARY_DAYLY + dbo.UIIF(dbo.Umonth(dbo.WORKING.WDATE) * 100 + dbo.Uday(dbo.WORKING.WDATE), N'>', dbo.Umonth(dbo.PERSONEL.WSDATE) * 100 + dbo.Uday(dbo.PERSONEL.WSDATE), @Forms___Baseknow___HSANP, 0) AS SALARY_DAYLY, dbo.PHOKM.SALARY_DAYLYB + dbo.UIIF(dbo.Umonth(dbo.WORKING.WDATE) * 100 + dbo.Uday(dbo.WORKING.WDATE), N'>', dbo.Umonth(dbo.PERSONEL.WSDATE) * 100 + dbo.Uday(dbo.PERSONEL.WSDATE), @Forms___Baseknow___HSANP, 0) AS SALARY_DAYLYB, dbo.PHOKM.HOME, dbo.PHOKM.CHILDREN, dbo.PHOKM.HAGHTAHOL, dbo.PHOKM.CONDITIONS, dbo.PHOKM.BON, dbo.PHOKM.JAZB, dbo.PHOKM.SAYER, dbo.PERSONEL.TAB56, (dbo.UIIF(@Forms___Baseknow___HSAY, N'=', - 1, dbo.PHOKM.SAYER, 0) + dbo.UIIF(@Forms___Baseknow___HSHI, N'=', - 1, CAST(dbo.PHOKM.HSHIFT / 100 * dbo.PHOKM.SALARY_DAYLY AS int), 0) + dbo.UIIF(@Forms___Baseknow___HJAZ, N'=', - 1, dbo.PHOKM.JAZB, 0) + dbo.UIIF(@Forms___Baseknow___HNAH, N'=', - 1, dbo.PHOKM.BON, 0) + dbo.UIIF(@Forms___Baseknow___HCON, N'=', - 1, dbo.PHOKM.CONDITIONS, 0) + dbo.UIIF(@Forms___Baseknow___HTAHOL, N'=', - 1, dbo.PHOKM.HAGHTAHOL, 0)) * dbo.WORKING.DAYS + dbo.UIIF(@Forms___Baseknow___HKHA, N'=', - 1, dbo.UIIF(dbo.WORKING.DAYS, N'>', 27, dbo.PHOKM.HOME, ROUND(CAST(dbo.PHOKM.HOME AS DECIMAL(18,6)) / (case when @Forms___F_MENU_BIM___MMO <7 then 31 else 30 end)  * dbo.WORKING.DAYS, 0)), 0) + dbo.UIIF(@Forms___Baseknow___HEZA, N'=', - 1, dbo.WORKING.EZAFAH, 0) + dbo.UIIF(@Forms___Baseknow___HBON, N'=', - 1, dbo.UIIF(dbo.WORKING.DAYS, N'>', 27, dbo.PHOKM.bonj, ROUND(CAST(dbo.PHOKM.bonj AS DECIMAL(18,6)) / (case when @Forms___F_MENU_BIM___MMO <7 then 31 else 30 end)  * dbo.WORKING.DAYS, 0)), 0) AS MAZMASH, dbo.UIIF(@Forms___Baseknow___HOLA, N'=', - 1, dbo.UIIF(dbo.WORKING.DAYS, N'>', 27, dbo.PHOKM.CHILDREN, ROUND(CAST(dbo.PHOKM.CHILDREN AS DECIMAL(18,6)) / (case when @Forms___F_MENU_BIM___MMO <7 then 31 else 30 end)  * dbo.WORKING.DAYS, 0)), 0) AS CHI, dbo.UIIF(dbo.Umonth(dbo.WORKING.WDATE) * 100 + dbo.Uday(dbo.WORKING.WDATE), N'>', dbo.Umonth(dbo.PERSONEL.WSDATE) * 100 + dbo.Uday(dbo.PERSONEL.WSDATE), @Forms___Baseknow___HSANP, 0) AS Expr1, dbo.PERSONEL.DIHARD, dbo.PERSONEL.MELLICOD, dbo.PHOKM.ISCEO FROM dbo.PERSONEL INNER JOIN dbo.PHOKM ON dbo.PERSONEL.CODE = dbo.PHOKM.CODE INNER JOIN dbo.WORKING ON dbo.PERSONEL.CODE = dbo.WORKING.PCODE INNER JOIN dbo.LASTHOKM(@HOKMDATE) AS LASTHOKM ON dbo.PHOKM.HONUM = LASTHOKM.MaxOfHONUM AND dbo.PHOKM.CODE = LASTHOKM.CODE WHERE dbo.Umonth(dbo.WORKING.WDATE) = @Forms___F_MENU_BIM___MMO)
